/// The version of a beta struct: vanilla's sentinel `9999.9999.9999-beta`, which the literal
/// `"format_version": "beta"` stands for.
pub const BETA_VERSION: FormatVersion = FormatVersion::new(9999, 9999, 9999);

/// A version struct: the `format_version` it parses.
pub trait Versioned {
    /// The struct's version; [`BETA_VERSION`] for a beta struct.
    const VERSION: FormatVersion;
}

/// One typed upgrade step from a version struct to the next.
pub trait Upgrade: Versioned + Sized {
    /// The next struct in the chain.
    type Next: Versioned;
    /// Carries the value forward one version.
    fn upgrade(self, cx: &mut UpgradeCx<'_>) -> Self::Next;
}

/// One struct of a chain as the chain parses and writes it: the payload (or, on the raw-text
/// path, the whole document) as written in the struct's era.
///
/// Most structs parse with [`parse_payload`] and write with [`write_payload`]; a struct that
/// holds components keeps them as raw slices while it parses and builds its component map with
/// [`parse_component_map`].
pub trait VersionStruct: Versioned + MolangFields + Sized {
    /// Parses `payload`; `None` when the struct cannot be built (the reason is in `d`).
    fn parse(payload: JsonSlice<'_>, cx: &ParseCx<'_>, d: &mut Diagnostics) -> Option<Self>;
    /// The struct as JSON, in its own version's shape.
    ///
    /// # Errors
    ///
    /// Returns `EncodeError` when the struct has no JSON form.
    fn write(&self) -> Result<Value, EncodeError>;
}

/// What a struct's parse sees besides the text.
#[derive(Clone, Debug)]
pub struct ParseCx<'a> {
    /// The pack's load context.
    pub load: &'a LoadContext,
    /// The version the envelope gave (for a missing one, the effective version); the Molang
    /// fields whose version is the document's take it from here.
    pub written: FormatVersionInput,
    /// The version gates compare against: the file's, the family's floor when absent.
    pub original_version: FormatVersion,
    /// Where the payload is in the file: the payload key, or the root on the raw-text path.
    /// Findings of the parse are reported below it.
    pub at: JsonPath,
}

/// What an upgrade step sees.
#[derive(Debug)]
pub struct UpgradeCx<'a> {
    /// The pack's load context (`min_engine_version`, Molang version).
    pub load: &'a LoadContext,
    /// The file's original `format_version` (the effective one when it was absent).
    pub original_version: FormatVersion,
    /// The document's identifier (`""` when the family has none or the payload names none).
    pub identifier: &'a str,
    /// Vanilla's actor type of the identifier (`Mob` for a custom entity and for every
    /// family other than entity).
    pub actor_type: ActorType,
    /// Suppress the version-gated upgrade ops (`Family::SKIP_UPGRADES_KEY` present in the payload,
    /// or `original_version >= ENGINE_VERSION`).
    pub skip_section_a: bool,
    /// Where the step reports.
    pub diagnostics: &'a mut Diagnostics,
}

/// The result of a chain walk: the newest stable struct or the beta struct.
pub enum Loaded<F: Family> {
    /// The newest stable struct.
    Stable(F::Latest),
    /// The beta struct, unchanged.
    Beta(F::Beta),
}

impl<F: Family> Clone for Loaded<F>
where
    F::Latest: Clone,
    F::Beta: Clone,
{
    fn clone(&self) -> Self {
        match self {
            Self::Stable(v) => Self::Stable(v.clone()),
            Self::Beta(v) => Self::Beta(v.clone()),
        }
    }
}

impl<F: Family> fmt::Debug for Loaded<F>
where
    F::Latest: fmt::Debug,
    F::Beta: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Stable(v) => f.debug_tuple("Stable").field(v).finish(),
            Self::Beta(v) => f.debug_tuple("Beta").field(v).finish(),
        }
    }
}

impl<F: Family> PartialEq for Loaded<F>
where
    F::Latest: PartialEq,
    F::Beta: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Stable(a), Self::Stable(b)) => a == b,
            (Self::Beta(a), Self::Beta(b)) => a == b,
            _ => false,
        }
    }
}

/// What [`load`] produced.
pub struct LoadOutcome<F: Family> {
    /// The value, or `None` when the document was rejected (then `diagnostics` holds an
    /// error).
    pub value: Option<Loaded<F>>,
    /// The file's original `format_version`: the effective version gates compared against
    /// ([`BETA_VERSION`] for a beta document).
    pub original_version: FormatVersion,
    /// What the file said about its version and what the load did with it, for the
    /// document's `VersionInfo`.
    pub version: crate::document::VersionInfo,
    /// Every finding, in the order the load raised them.
    pub diagnostics: Diagnostics,
}

impl<F: Family> fmt::Debug for LoadOutcome<F>
where
    F::Latest: fmt::Debug,
    F::Beta: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("LoadOutcome")
            .field("value", &self.value)
            .field("original_version", &self.original_version)
            .field("version", &self.version)
            .field("diagnostics", &self.diagnostics)
            .finish()
    }
}

/// The newest stable struct of a beta-only family: uninhabited, `VERSIONS = []`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NoStable {}

impl MolangFields for NoStable {
    fn visit_molang(&mut self, _: &mut MolangVisitor<'_>) {
        match *self {}
    }
}

/// The beta struct of a family without one holds no Molang field.
impl MolangFields for std::convert::Infallible {
    fn visit_molang(&mut self, _: &mut MolangVisitor<'_>) {
        match *self {}
    }
}

impl Versioned for NoStable {
    /// Never compared: a beta-only family has no stable struct and no range.
    const VERSION: FormatVersion = FormatVersion::new(0, 0, 0);
}

/// The component set of a family without components: uninhabited, with an empty table.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NoComponents {}

impl ComponentSet for NoComponents {
    fn name(&self) -> Option<&'static str> {
        match *self {}
    }
}

/// What family validation sees: the load context, the original version, and where to report.
#[derive(Debug)]
pub struct ValidateCx<'a> {
    /// The pack's load context.
    pub load: &'a LoadContext,
    /// The file's original `format_version` (the effective one when it was absent).
    pub original_version: FormatVersion,
    /// The payload's path in the file (the payload key, or the root on the raw-text path).
    pub at: JsonPath,
    /// The optional component sections that failed a `requires` gate, by the path
    /// [`ComponentSection::at`] gave them: the family drops them (vanilla skips a permutation
    /// that carries a gated component).
    pub skipped: Vec<JsonPath>,
    /// The Molang fields that did not pass the compile check (pass 2 ran with
    /// `LoadContext::molang` before `validate`), for the family's failure rules
    /// (`MolangFieldSpec::on_failure`).
    #[cfg(feature = "molang")]
    #[cfg_attr(docsrs, doc(cfg(feature = "molang")))]
    pub molang_failures: Vec<crate::molang::FieldOutcome>,
    /// Where validation reports. An error rejects the document.
    pub diagnostics: &'a mut Diagnostics,
}

/// What a payload says about itself before its struct is parsed: `description.identifier` and
/// `description.runtime_identifier`, when they are strings.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Identity {
    /// `description.identifier`.
    pub identifier: Option<String>,
    /// `description.runtime_identifier`.
    pub runtime_identifier: Option<String>,
}

/// What a family does with a document whose envelope has no `format_version` (and whose
/// payload gives none, `Family::payload_version`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MissingVersion {
    /// Parse the document at the family's floor, telling a `MissingFormatVersion` with `text`
    /// at `severity`; `None` tells nothing (trading). The default tells the crate's own
    /// information, with no text of the game.
    Floor {
        /// The text of the finding; `None` for none of the game's.
        text: Option<VanillaText>,
        /// The severity of the finding; `None` for no finding, and then `text` is not read:
        /// `Floor { text: Some(..), severity: None }` tells nothing, like `text: None`.
        severity: Option<Severity>,
    },
    /// Reject the document with a `MissingFormatVersion` error.
    Reject {
        /// The error's text; `None` gives the game's version-check text ("no valid version
        /// passed by the caller or found in the input", `VanillaText::NoValidVersion`).
        text: Option<VanillaText>,
    },
}

impl MissingVersion {
    /// The default: parsed at the floor with the crate's own information.
    pub const FLOOR: Self = Self::Floor {
        text: None,
        severity: Some(Severity::Info),
    };
    /// Rejected with the game's version-check text.
    pub const REJECT: Self = Self::Reject { text: None };
}

/// What a family fixes about each of its files, before a struct is selected: the input kind,
/// whether the envelope's shape is checked, what an absent `format_version` does, what a
/// version below the floor is told, the clamp beyond a double and the duplicates kept.
/// `Family::ENVELOPE`; a family states the fields it changes and takes the rest from
/// [`DEFAULT`](Self::DEFAULT):
///
/// ```ignore
/// const ENVELOPE: Envelope = Envelope {
///     check: EnvelopeCheck::Never,
///     missing: MissingVersion::REJECT,
///     ..Envelope::DEFAULT
/// };
/// ```
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Envelope {
    /// The input kind of the family's files: where the version is read from, whether a JSON
    /// text is sized, and the default reading of every slice. Default [`InputKind::FirstRun`].
    pub input: InputKind,
    /// Whether the envelope's shape is checked. Default [`EnvelopeCheck::Always`].
    pub check: EnvelopeCheck,
    /// What an absent `format_version` does. Default [`MissingVersion::FLOOR`].
    pub missing: MissingVersion,
    /// What a document below [`Family::FLOOR`] is told. Default
    /// [`BelowFloor::UseFormatVersion`].
    pub below_floor: BelowFloor,
    /// Whether a number of the document that no double holds (`1e999`, an integer of 400
    /// digits) is read as the largest finite double of its sign, with an `InvalidValue`
    /// warning at the number (`json::clamp_beyond_double`). For a family that keeps what it
    /// does not read (unknown members, members held as JSON) for write-back: an infinity kept
    /// there has no JSON spelling, and the loaded document could not be written. Default
    /// `false`, which leaves the number to the family's readers.
    pub clamps_beyond_double: bool,
    /// Members whose object value keeps the members written twice in it, at any depth: the
    /// family's own rule reads them (block: `components`). Everywhere else the last value of a
    /// member written twice stands, whole. Default none.
    pub duplicates_kept_in: &'static [&'static str],
}

impl Envelope {
    /// Every field at its default.
    pub const DEFAULT: Self = Self {
        input: InputKind::FirstRun,
        check: EnvelopeCheck::Always,
        missing: MissingVersion::FLOOR,
        below_floor: BelowFloor::UseFormatVersion,
        clamps_beyond_double: false,
        duplicates_kept_in: &[],
    };

    /// Whether a text from `source` gets the JSON size check: a document input
    /// ([`VersionInput::Document`]) read from JSON (an MCB source is a binary input).
    pub const fn sizes_json(&self, source: crate::load::DocumentSource) -> bool {
        matches!(self.input.version_input(), VersionInput::Document)
            && matches!(source, crate::load::DocumentSource::Json)
    }
}

impl Default for Envelope {
    fn default() -> Self {
        Self::DEFAULT
    }
}

/// Whether the envelope's shape is checked: vanilla checks it only when the
/// loader's minimum version is valid and the document is not below it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EnvelopeCheck {
    /// Exactly two root members, the payload under the family's key; the payload is parsed.
    Always,
    /// The raw-text path: the root struct is parsed from the whole document, and a third root
    /// member is an unknown member of it (dimension, camera presets, aim assist, spawn with
    /// the experiment off).
    Never,
    /// The raw-text path below this version (or without one, or at a pre-release of it, which
    /// sorts below it), the checked envelope at or above it (particle, 1.20.80).
    From(FormatVersion),
    /// The payload under the family's key, the root's members not counted: a root member
    /// beside the version and the payload is read by nothing and told (`UnrecognizedField`
    /// warning), and the document loads (the item loader, which never runs the two-member
    /// check).
    Uncounted,
}

/// Where a family's loader reads the document's `format_version` from: the input kind the game
/// builds for the family's files.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub enum VersionInput {
    /// The envelope's root member: a string or three integers; a number, a bool, `null` or an
    /// object is malformed. The `JsonCpp` families (entity, features, the item legacy chain)
    /// read the version this way.
    #[default]
    Root,
    /// The document input's reading: the first textual `"format_version"` of the file,
    /// wherever it is, with a number read as its text (`1` is 1.0.0, `1.21` is 1.21.0); a
    /// present value that gives no version is malformed. The JSON size limits apply. A family
    /// gets it by declaring `InputKind::Document`.
    Document,
}

/// The result-code mask a slice is registered with: which findings of the parse reject the
/// document.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub enum ErrorMask {
    /// An unknown member (code `0x4`) or component (code `0x400`) is a warning and the
    /// document is kept. The default.
    #[default]
    Unstrict,
    /// An unknown member or component of the payload is an error and the document is
    /// rejected.
    Strict,
}

/// The input kind the game builds for a family's files, in one place: it says where the
/// version is read from ([`VersionInput`]) and, by default, how each slice reads
/// ([`profile`](Self::profile)). A family declares it once, as `Family::ENVELOPE.input`.
///
/// `JsonCpp` is entity, features and the item's legacy component chain; `Document` is every
/// other Cereal family (block, the modern item, biome, client biome, dimension, cameras, aim
/// assist, POI, trade, catalog, persona, voxel shape, sounds, DDUI, UI style, atomic client
/// entity, culling, jigsaw, feature rules, particle, render configs, fog, manifest v3). A
/// family that has not declared its kind reads as `FirstRun`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub enum InputKind {
    /// The version from the root member ([`VersionInput::Root`]), and `null` as each read of
    /// the family takes it (the framework applies no null rule).
    #[default]
    FirstRun,
    /// The version from the root member, and a member written as `null` is absent
    /// ([`NullRule::Absent`](crate::json::NullRule)); the game's JSON-parsed families
    /// (entity, features) read this way.
    JsonCpp,
    /// The version as the document input reads it ([`VersionInput::Document`], with its size
    /// limits), and a `null` where a value is read is a type error
    /// ([`NullRule::Rejected`](crate::json::NullRule)).
    Document,
}

impl InputKind {
    /// Where the version is read from.
    pub const fn version_input(self) -> VersionInput {
        match self {
            Self::FirstRun | Self::JsonCpp => VersionInput::Root,
            Self::Document => VersionInput::Document,
        }
    }

    /// How every slice of a family of this kind reads, the default of `Family::reading`:
    /// [`Reading::OWN`] for `FirstRun`, [`Reading::NULL_ABSENT`] for `JsonCpp`,
    /// [`Reading::DOCUMENT`] for `Document`.
    pub const fn profile(self) -> Reading {
        match self {
            Self::FirstRun => Reading::OWN,
            Self::JsonCpp => Reading::NULL_ABSENT,
            Self::Document => Reading::DOCUMENT,
        }
    }
}

/// Which struct of a chain parses a document.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StructIndex {
    /// `VERSIONS[i]`.
    Stable(usize),
    /// The beta struct.
    Beta,
}

/// A versioned family: one chain of structs, its payload key, floor and range model.
pub trait Family: Sized + 'static {
    /// `"item"`: used in messages.
    const NAME: &'static str;
    /// `"minecraft:item"`; one `Family` per feature type.
    const PAYLOAD_KEY: &'static str;
    /// The oldest version the chain parses: the first struct's range starts here.
    const FLOOR: FormatVersion;
    /// How `VERSIONS` become version ranges.
    const RANGE_MODEL: RangeModel = RangeModel::ClosedToEngine;
    /// The newest stable struct; [`NoStable`] for beta-only families.
    type Latest: VersionStruct;
    /// The beta struct; `Infallible` when the family has no beta struct.
    type Beta;
    /// Who may load beta documents.
    const BETA_PERMISSION: BetaPermission = BetaPermission::BetaApisOrBaseGame;
    /// Who may load this beta document, given its payload object and the load context: a
    /// family whose input formats gate beta differently (item: JSON by the toggle alone, MCB
    /// by the pack-version check) chooses here. Default
    /// [`BETA_PERMISSION`](Self::BETA_PERMISSION).
    #[allow(unused_variables)]
    fn beta_permission(payload: JsonSlice<'_>, cx: &LoadContext) -> BetaPermission {
        Self::BETA_PERMISSION
    }
    /// The family's closed component enum ([`NoComponents`] for a family without
    /// components).
    type Component: ComponentSet;
    /// The chain, generated by `version_chain!`.
    type Any: VersionChain<Self>;
    /// What a gated component is called in "To use %s '%s' …" (`"item component"`).
    const COMPONENT_NOUN: &'static str = "component";
    /// The family's component table (`<Enum>::TABLE` of `#[derive(Components)]`). The empty
    /// table by default, for a family without components (`type Component = NoComponents`); a
    /// family with components overrides it, or its documents read no component at all.
    fn components() -> &'static ComponentTable<Self> {
        &ComponentTable::EMPTY
    }
    /// Family rules on the loaded value, after the generic per-component checks; may drop
    /// parts of it (the sections in `cx.skipped`, a failed Molang field) and reports to
    /// `cx.diagnostics`, where an error rejects the document. The Molang compile check (pass
    /// 2, `molang::check_fields` with the `molang` feature, else `molang::not_checked`) runs
    /// here on the newest struct, because its failure rules are the family's.
    #[allow(unused_variables)]
    fn validate(v: &mut Loaded<Self>, cx: &mut ValidateCx<'_>) {}
    /// A payload member that suppresses the version-gated upgrade ops (entity:
    /// `do_not_upgrade`).
    const SKIP_UPGRADES_KEY: Option<&'static str> = None;
    /// The envelope rules of the family's files, fixed before a struct is selected: the
    /// input kind, the shape check, what an absent `format_version` does, what a version below
    /// [`FLOOR`](Self::FLOOR) is told, the clamp beyond a double and the members whose
    /// duplicates are kept. Default [`Envelope::DEFAULT`].
    const ENVELOPE: Envelope = Envelope::DEFAULT;
    /// How the slice `index` reads a document from `source`: the null rule and whether a
    /// component that fails to read is fatal, which the pipeline puts on the context of the
    /// parse, and the error mask of the parse and of the validate phase's component checks. The
    /// default is the profile of [`ENVELOPE.input`](Envelope::input)
    /// ([`InputKind::profile`]). An MCB source is read by the binary reader: the pipeline
    /// reads it under no null rule whatever this says, and a family does not state that.
    ///
    /// Four local overrides the families make stay in their readers, outside this:
    ///
    /// - block's legacy slice forces strict components and reads scalars non-strictly
    ///   (`families/block/src/parse.rs`);
    /// - item's legacy slice forces strict components for the parse but grades its range
    ///   members by the unforced flag (`families/item/src/history/document.rs`);
    /// - camera preset's slice 0 coerces scalars through `typed_unstrict`;
    /// - dimension filters its null rule by `original_version`
    ///   (`families/dimension/src/parse.rs`).
    #[allow(unused_variables)]
    fn reading(index: StructIndex, source: crate::load::DocumentSource) -> Reading {
        Self::ENVELOPE.input.profile()
    }
    /// The post-parse hook a file's load closes with: rewrites the generic findings of a
    /// parse into the family's vanilla texts and, when the file `failed`, adds the family's
    /// closing line. `document` is the text, when it is one; `path` is the file's. The
    /// default does nothing. The closed entries ([`load_file`], [`finish_file`]) call it once
    /// per file; [`parse_file_as_written`] calls it only for a parse with no value (`failed`),
    /// and a successful one is not closed, its [`finish_file`] closes the file; the unclosed
    /// ones never do.
    #[allow(unused_variables)]
    fn close(
        diagnostics: &mut Diagnostics,
        document: Option<JsonSlice<'_>>,
        path: &crate::pack_identity::PackPath,
        failed: bool,
    ) {
    }
    /// The severity of `EmptyDocument` for an empty file (it is never loaded).
    const EMPTY_DOCUMENT: Severity = Severity::Error;
    /// A content-sensitive routing hook: the index into `VERSIONS` of the struct that parses
    /// `payload`, for a version the range model accepts; `None` = version-only dispatch.
    #[allow(unused_variables)]
    fn route(payload: JsonSlice<'_>, v: FormatVersionInput, cx: &LoadContext) -> Option<usize> {
        None
    }
    /// The version a payload gives when the envelope has none (entity: the payload's own
    /// `format_version`, read with [`member_version`]); `None` by default. Consulted before
    /// `ENVELOPE.missing`.
    #[allow(unused_variables)]
    fn payload_version(payload: JsonSlice<'_>) -> Option<FormatVersionInput> {
        None
    }
    /// The payload's identity before parsing, for messages and `UpgradeCx::identifier`.
    /// Default: `description.identifier` and `description.runtime_identifier`.
    fn identity(payload: JsonSlice<'_>) -> Identity {
        pipeline::description_identity(payload)
    }
    /// `UpgradeCx::actor_type`; `Mob` by default (entity: `ActorType::for_entity`).
    #[allow(unused_variables)]
    fn actor_type(identity: &Identity) -> ActorType {
        ActorType::Mob
    }
    /// Every component map of the newest struct, for the generic per-component checks.
    #[allow(unused_variables)]
    fn component_sections(v: &mut Self::Latest) -> Vec<ComponentSection<'_, Self::Component>> {
        Vec::new()
    }
}

/// The generated chain of a family: struct selection, parse and the upgrade walk.
///
/// `version_chain!` implements every item; a hand-written chain needs only `VERSIONS`, `parse`
/// and `upgrade_to_end`.
pub trait VersionChain<F: Family>: Sized {
    /// Ascending struct versions; [`check_chain`] asserts them per family.
    const VERSIONS: &'static [FormatVersion];
    /// The chain has a beta struct.
    const HAS_BETA: bool = false;
    /// Parses the payload with the struct `v` selects under the family's range model (no
    /// routing hook); `UnsupportedVersion` when no struct covers it.
    fn parse(
        payload: JsonSlice<'_>,
        v: FormatVersion,
        cx: &LoadContext,
        d: &mut Diagnostics,
    ) -> Option<Self>;
    /// Parses the payload with the struct `index` names, then runs Molang pass 1 over it with
    /// the document's version. The default parses a stable struct by its version through
    /// [`parse`](Self::parse) and has no beta struct.
    fn parse_struct(
        payload: JsonSlice<'_>,
        index: StructIndex,
        cx: &ParseCx<'_>,
        d: &mut Diagnostics,
    ) -> Option<Self> {
        match index {
            StructIndex::Stable(i) => Self::parse(payload, *Self::VERSIONS.get(i)?, cx.load, d),
            StructIndex::Beta => None,
        }
    }
    /// Hands the loaded value's Molang walk to `visit` (pass 2 of [`load`]); a hand-written
    /// chain walks nothing.
    #[doc(hidden)]
    #[allow(unused_variables)]
    fn with_molang(loaded: &mut Loaded<F>, visit: &mut dyn FnMut(&mut dyn MolangFields)) {}
    /// Walks the remaining `Upgrade` steps; a beta struct is returned as `Loaded::Beta` unchanged.
    fn upgrade_to_end(self, cx: &mut UpgradeCx<'_>) -> Loaded<F>;
}

/// How `VERSIONS` become version ranges; `V_i = VERSIONS[i]`, `V_last = Latest::VERSION`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RangeModel {
    /// `[V_i, V_{i+1}) …, [V_last, ENGINE_VERSION]`: the game's sliced loaders whose last
    /// slice ends at the engine version.
    ClosedToEngine,
    /// `[V_i, V_{i+1}) …, [V_last, V_last]`: the game's sliced loaders whose last slice ends
    /// at the newest struct's version.
    ClosedToLatest,
    /// `[V_i, V_i]` for every struct: the game's parsers bound to one exact version, or an
    /// exact `==` switch.
    ExactOnly,
    /// `[V_i, V_{i+1}) …, [V_last, ENGINE_VERSION)`: the game's loaders with an explicit
    /// version range whose end is excluded.
    HalfOpenToEngine,
}

/// Who may load a family's beta documents, and what a refusal says.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum BetaPermission {
    /// The pack-version check of the Cereal parser: the Beta APIs toggle or a base-game pack; a
    /// refusal says "Using a beta `format_version` is only allowed for base packs or when the
    /// `BetaApis` toggle is enabled."
    BetaApisOrBaseGame,
    /// Anyone (atomic client entities: vanilla hard-codes the permission on).
    Always,
    /// The Beta APIs toggle alone, a base-game pack included; a refusal says "Turn on the Beta
    /// APIs toggle in settings to allow beta documents." (the JSON item path).
    BetaApis,
}

/// One field of a component and the engine version that introduced it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FieldMeta {
    /// A dotted path inside the component; `""` = the whole component.
    pub name: &'static str,
    /// The engine version that introduced it.
    pub since_engine: FormatVersion,
}

/// One member of a component, or of a payload, and the format version whose struct first has
/// it: below that version the member is refused as vanilla's strict loaders refuse a member
/// the struct does not bind.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FieldGate {
    /// A dotted path inside the owner (`"underwater_music"`, `"color.color_map"`).
    pub name: &'static str,
    /// The first format version that has the member.
    pub released: FormatVersion,
}

/// A member of a beta struct that only loads with an experiment on: the game refuses the
/// member while the experiment is off.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ExperimentalField {
    /// A dotted path inside the owner (`"components.minecraft:x.flag"`).
    pub name: &'static str,
    /// The experiment that must be on.
    pub experiment: crate::load::Experiment,
}

/// Which context a component may appear in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ContextArea {
    /// Any pack.
    Public,
    /// Base-game packs only.
    Vanilla,
    /// Internal: base-game packs only.
    Internal,
}

/// How a component's parser treats coerced values.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConvertMode {
    /// As written.
    Strict,
    /// Converted in a step from an older document (vanilla's entity legacy callbacks).
    Lenient,
}

/// A component parser: the component's slice of the file (with its offset), how lenient to
/// be, the load context and where to report, findings at paths relative to the component.
pub type ParseFn<C> = fn(JsonSlice<'_>, ConvertMode, &LoadContext, &mut Diagnostics) -> Option<C>;

/// One row of a family's component table.
pub struct ComponentMeta<F: Family> {
    /// The JSON key.
    pub name: &'static str,
    /// The first format version that has the component; `None` = never released.
    pub released: Option<FormatVersion>,
    /// The version the component was deprecated in.
    pub deprecated_since: Option<FormatVersion>,
    /// Family-specific vanilla text; `None` → the generic template.
    pub deprecated_message: Option<&'static str>,
    /// `"minecraft:glint"` supersedes `"minecraft:foil"`.
    pub supersedes: Option<&'static str>,
    /// Unlocks the component before `released`; ignored at/after it.
    pub requires: &'static [LoadRequirement],
    /// Which packs may use it.
    pub area: ContextArea,
    /// The fields and when they arrived.
    pub fields: &'static [FieldMeta],
    /// Parses the component's slice; findings are relative to the component.
    pub parse: ParseFn<F::Component>,
}

impl<F: Family> Clone for ComponentMeta<F> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<F: Family> Copy for ComponentMeta<F> {}

impl<F: Family> fmt::Debug for ComponentMeta<F> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ComponentMeta")
            .field("name", &self.name)
            .field("released", &self.released)
            .field("deprecated_since", &self.deprecated_since)
            .field("deprecated_message", &self.deprecated_message)
            .field("supersedes", &self.supersedes)
            .field("requires", &self.requires)
            .field("area", &self.area)
            .field("fields", &self.fields)
            .finish_non_exhaustive()
    }
}

/// A family's component table, sorted by name; binary search.
pub struct ComponentTable<F: Family>(pub &'static [ComponentMeta<F>]);

impl<F: Family> Clone for ComponentTable<F> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<F: Family> Copy for ComponentTable<F> {}

impl<F: Family> fmt::Debug for ComponentTable<F> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_list()
            .entries(self.0.iter().map(|meta| meta.name))
            .finish()
    }
}

impl<F: Family> ComponentTable<F> {
    /// The table without rows.
    pub const EMPTY: Self = Self(&[]);

    /// The row named `name`.
    pub fn get(&self, name: &str) -> Option<&ComponentMeta<F>> {
        let i = self.0.binary_search_by(|meta| meta.name.cmp(name)).ok()?;
        self.0.get(i)
    }

    /// Whether the rows are sorted by name and each name occurs once.
    pub fn is_sorted(&self) -> bool {
        self.0.windows(2).all(|pair| pair[0].name < pair[1].name)
    }
}
